// Ignore waits; room is warm iff the turn sequence contains a down-then-up that is not preceded by up-up and not followed by down.
function visible(actions) {
  const turns = actions
    .filter(a => a !== "wait")
    .map(a => (a === "turn up" ? "u" : "d"))
    .join("");

  for (let i = 0; i < turns.length - 1; i++) {
    if (turns[i] === "d" && turns[i + 1] === "u") {
      const precededByUU = i >= 2 && turns[i - 2] === "u" && turns[i - 1] === "u";
      const followedByD = i + 2 < turns.length && turns[i + 2] === "d";
      if (!precededByUU && !followedByD) {
        return { room: "warm" };
      }
    }
  }

  return { room: "cold" };
}

