function visible(actions) {
  // The dial starts at 2; turn up lowers it, turn down raises it (clamped 0..3).
  // The room is warm iff the final dial is 1 or 2 and the dial never reached 0.
  let dial = 2;
  let visited0 = false;
  for (const action of actions) {
    if (action === "turn up") {
      dial = Math.max(0, dial - 1);
    } else if (action === "turn down") {
      dial = Math.min(3, dial + 1);
    }
    // "wait" leaves the dial unchanged.
    if (dial === 0) visited0 = true;
  }
  const warm = (dial === 1 || dial === 2) && !visited0;
  return { room: warm ? "warm" : "cold" };
}

